/**
 * DI4A website — client application (vanilla ES module, no build step).
 *
 * Responsibilities
 *  - i18n: the page language is fixed at build time (EN at "/", FR at "/fr/");
 *    the EN | FR switch stores the choice and navigates to the alternate page
 *  - catalogue: loads data/catalog.json (generated by scripts/build_site.py)
 *  - rendering: key figures, theme cards, document cards, search & filters
 *  - bilingual cards: one card per document, one face per language, 3D flip
 *  - interactions: 3D tilt, count-up numbers, mobile navigation, PDF preview
 *    (lazy module), ZIP of both language versions (lazy JSZip)
 */
import { injectIconSprite, iconName } from './icons.js';

const ROOT = document.documentElement.dataset.root || './';
const HOME = document.documentElement.dataset.home || ROOT; // root of the current language version
const PAGE = document.body.dataset.page || 'home';
const STORAGE_KEY = 'di4a.lang';
const CASCADE_KEY = 'di4a.cascade';
const SUPPORTED = ['en', 'fr'];
const REDUCED_MOTION = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const FINE_POINTER = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
const JSZIP_URL = 'https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js';

const state = {
  lang: 'en',
  dict: {},
  catalog: null,
  filters: { q: '', type: 'all', lang: 'all' },
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const $ = (sel, root = document) => root.querySelector(sel);
const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const icon = (name, cls = 'icon') => `<svg class="${cls}" aria-hidden="true"><use href="#i-${iconName(name)}"/></svg>`;
const upper = (l) => String(l).toUpperCase();

/** Translate a dotted key, with optional `{var}` substitutions. */
function t(key, vars) {
  const value = key.split('.').reduce((o, k) => (o && typeof o === 'object' ? o[k] : undefined), state.dict);
  const text = typeof value === 'string' ? value : key;
  return vars ? text.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m)) : text;
}
const tn = (n, one, many) => t(n === 1 ? one : many, { n });

function formatDate(iso) {
  if (!iso) return '';
  try {
    return new Intl.DateTimeFormat(state.lang === 'fr' ? 'fr-FR' : 'en-GB', { year: 'numeric', month: 'short', day: 'numeric' })
      .format(new Date(`${iso}T00:00:00`));
  } catch { return iso; }
}

/** The page language is decided at build time (EN at the root, FR under /fr/). */
function detectLang() {
  const page = String(document.documentElement.lang || 'en').slice(0, 2).toLowerCase();
  return SUPPORTED.includes(page) ? page : 'en';
}

async function fetchJson(path) {
  const res = await fetch(path, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  return res.json();
}

function storage(action, key, value) {
  try {
    const store = action === 'session' ? sessionStorage : localStorage;
    if (value === undefined) return store.getItem(key);
    if (value === null) store.removeItem(key); else store.setItem(key, value);
  } catch { /* storage unavailable (private mode, blocked) */ }
  return null;
}

// ---------------------------------------------------------------------------
// i18n
// ---------------------------------------------------------------------------
/**
 * Switch language: remember the choice, then navigate to the same page in the
 * other language (pre-rendered by the build). Falls back to in-place
 * translation on pages that have no alternate (404).
 */
async function setLang(lang) {
  if (!SUPPORTED.includes(lang) || lang === state.lang) return;
  storage('local', STORAGE_KEY, lang);
  storage('session', CASCADE_KEY, state.lang); // lets the next page flip its bilingual cards
  const alt = document.documentElement.dataset[`alt${lang[0].toUpperCase()}${lang.slice(1)}`];
  if (alt) { location.href = alt + location.search + location.hash; return; }
  state.dict = await fetchJson(`${ROOT}i18n/${lang}.json`);
  state.lang = lang;
  applyI18n();
  renderAll();
}

function applyI18n() {
  document.documentElement.lang = state.lang;
  $$('[data-i18n]').forEach((el) => {
    let vars = null;
    if (el.dataset.i18nVars) { try { vars = JSON.parse(el.dataset.i18nVars); } catch { vars = null; } }
    if (el.dataset.i18n === 'footer.rights') vars = { ...(vars || {}), year: new Date().getFullYear() };
    el.textContent = t(el.dataset.i18n, vars);
  });
  $$('[data-i18n-attr]').forEach((el) => {
    el.dataset.i18nAttr.split(';').forEach((pair) => {
      const idx = pair.indexOf(':');
      if (idx < 0) return;
      const attr = pair.slice(0, idx).trim();
      const key = pair.slice(idx + 1).trim();
      if (attr && key) el.setAttribute(attr, t(key));
    });
  });
  $$('.lang-btn').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.lang === state.lang)));
  if (PAGE === 'home') document.title = t('meta.site_title');
  if (PAGE === '404') document.title = `${t('notfound.title')} — DI4A`;
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------
function currentTheme() {
  const id = document.body.dataset.themeId;
  return state.catalog?.themes.find((th) => th.id === id) || null;
}

/** Unified documents (one per EN/FR pair) of the current page, with their theme. */
function allDocs() {
  if (!state.catalog) return [];
  const themes = PAGE === 'theme' ? [currentTheme()].filter(Boolean) : state.catalog.themes;
  return themes.flatMap((th) => th.documents.map((d) => ({ ...d, theme: th })));
}

/** Lookup key unique across themes (ids are unique within a theme only). */
const docKey = (d) => `${d.theme.id}/${d.id}`;

function findDoc(key) {
  return allDocs().find((d) => docKey(d) === key) || null;
}

function renderAll() {
  if (!state.catalog) return;
  renderSiteLinks();
  if (PAGE === 'home') { renderStats(); renderThemes(); }
  if (PAGE === 'theme') renderThemeHero();
  renderDocs();
}

function renderSiteLinks() {
  const site = state.catalog.site || {};
  const repo = $('#repo-link');
  if (repo && site.repo_url) repo.href = site.repo_url;
  const credits = $('#image-credits');
  if (credits) {
    const items = site.image_credits || [];
    credits.innerHTML = items.length
      ? items.map((c) => `<li>${c.url ? `<a href="${esc(c.url)}" rel="noopener" target="_blank">${esc(c.label)}</a>` : esc(c.label)}</li>`).join('')
      : '<li>—</li>';
  }
}

function renderStats() {
  const s = state.catalog.stats || {};
  $$('[data-stat]').forEach((el) => {
    const target = Number(s[el.dataset.stat] ?? 0);
    if (el.dataset.done === String(target)) return;
    el.dataset.done = String(target);
    // Pre-rendered at build time: nothing to animate (and no layout shift).
    if (el.textContent.trim() === String(target)) return;
    countUp(el, target);
  });
}

function countUp(el, target) {
  if (REDUCED_MOTION || target === 0) { el.textContent = String(target); return; }
  const start = performance.now();
  const duration = 900;
  const tick = (now) => {
    const p = Math.min(1, (now - start) / duration);
    const eased = 1 - Math.pow(1 - p, 3);
    el.textContent = String(Math.round(target * eased));
    if (p < 1) requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

function themeCard(th) {
  const L = state.lang;
  const total = th.counts.lab + th.counts.presentation + (th.counts.resource || 0);
  const cover = th.cover
    ? `<img src="${esc(ROOT + th.cover)}" alt="" loading="lazy" decoding="async" width="600" height="338">`
    : `<span class="theme-cover-fallback">${icon(th.icon)}</span>`;
  return `
    <article class="theme-card tilt" data-tilt-max="6">
      <div class="theme-cover">${cover}<span class="theme-icon" aria-hidden="true">${icon(th.icon)}</span></div>
      <div class="theme-body">
        <h3><a href="${esc(`${HOME}themes/${th.id}/`)}">${esc(th.title[L])}</a></h3>
        <p>${esc(th.description[L])}</p>
        <div class="theme-meta">
          ${th.counts.lab ? `<span class="chip">${icon('flask')}${esc(tn(th.counts.lab, 'themes.lab', 'themes.labs'))}</span>` : ''}
          ${th.counts.presentation ? `<span class="chip chip-gold">${icon('file-text')}${esc(tn(th.counts.presentation, 'themes.presentation', 'themes.presentations'))}</span>` : ''}
          ${th.counts.resource ? `<span class="chip chip-archive">${icon('archive')}${esc(tn(th.counts.resource, 'themes.archive', 'themes.archives'))}</span>` : ''}
          <span class="chip chip-neutral">${esc(tn(total, 'themes.resource', 'themes.resources'))}</span>
        </div>
        <span class="theme-cta" aria-hidden="true">${esc(t('themes.explore'))}${icon('arrow-right')}</span>
      </div>
    </article>`;
}

function renderThemes() {
  const grid = $('#theme-grid');
  if (!grid) return;
  const themes = state.catalog.themes;
  grid.innerHTML = themes.length ? themes.map(themeCard).join('') : `<p class="muted">${esc(t('themes.empty'))}</p>`;
  grid.setAttribute('aria-busy', 'false');
}

function renderThemeHero() {
  const th = currentTheme();
  const L = state.lang;
  if (!th) {
    const grid = $('#doc-grid');
    if (grid) grid.innerHTML = `<p class="empty-state">${esc(t('theme.not_found'))}</p>`;
    return;
  }
  document.title = `${th.title[L]} — DI4A`;
  const bg = $('#theme-hero-bg');
  if (bg && th.cover) bg.style.backgroundImage = `url("${ROOT + th.cover}")`;
  const badge = $('#theme-icon');
  if (badge) badge.innerHTML = icon(th.icon);
  const stats = $('#theme-stats');
  if (stats) {
    stats.innerHTML = [
      th.counts.lab ? `<li><span class="chip">${icon('flask')}${esc(tn(th.counts.lab, 'themes.lab', 'themes.labs'))}</span></li>` : '',
      th.counts.presentation ? `<li><span class="chip">${icon('file-text')}${esc(tn(th.counts.presentation, 'themes.presentation', 'themes.presentations'))}</span></li>` : '',
      th.counts.resource ? `<li><span class="chip">${icon('archive')}${esc(tn(th.counts.resource, 'themes.archive', 'themes.archives'))}</span></li>` : '',
    ].join('');
  }
}

// ---------------------------------------------------------------------------
// Document cards (one card per document, one face per language version)
// ---------------------------------------------------------------------------
/** Language of the face shown first: the site language if that version exists. */
function initialFace(d) {
  return d.versions[state.lang] ? state.lang : d.langs[0];
}

function langToggle(d, face) {
  return `
    <div class="lang-toggle" role="radiogroup" aria-label="${esc(t('doc.version_lang'))}">
      ${d.langs.map((L) => `
        <button type="button" role="radio" lang="${L}" data-set-face="${L}"
                aria-checked="${String(L === face)}" tabindex="${L === face ? 0 : -1}"
                title="${esc(t(`doc.lang_${L}`))}">${upper(L)}</button>`).join('')}
      <span class="lang-toggle-thumb" aria-hidden="true"></span>
    </div>`;
}

function faceActions(d, v) {
  const L = v.lang;
  const tag = d.bilingual ? ` (${upper(L)})` : '';
  const links = v.links || {};
  const download = `<a class="btn btn-primary btn-3d" href="${esc(ROOT + v.file)}" download="${esc(v.download_name)}" title="${esc(t('doc.download_title', { name: v.download_name }))}">${icon('download')}<span>${esc(t('doc.download'))}${esc(tag)}</span></a>`;
  const zip = d.bilingual
    ? `<button type="button" class="btn btn-ghost btn-3d btn-zip" data-zip="${esc(docKey(d))}" title="${esc(t('doc.zip_title'))}">${icon('layers')}<span>${esc(t('doc.zip'))}</span></button>`
    : '';
  if (d.type === 'lab') {
    return `
      <a class="btn btn-ghost btn-3d" href="${esc(links.view || '#')}" target="_blank" rel="noopener" title="${esc(t('doc.view_title'))}">${icon('eye')}<span>${esc(t('doc.view'))}${esc(tag)}</span></a>
      <a class="btn btn-colab btn-3d" href="${esc(links.colab || '#')}" target="_blank" rel="noopener" title="${esc(t('doc.colab_title'))}">${icon('colab')}<span>${esc(t('doc.colab'))}${esc(tag)}</span></a>
      ${download}${zip}`;
  }
  if (d.type === 'resource') {
    // Archives: download only (no preview, no Colab).
    return `${download}${zip}`;
  }
  return `
      <button type="button" class="btn btn-gold btn-3d" data-preview="${esc(docKey(d))}" data-version="${L}" title="${esc(t('doc.preview_title'))}">${icon('eye')}<span>${esc(t('doc.preview'))}${esc(tag)}</span></button>
      ${download}${zip}`;
}

const TYPE_CHIP = {
  lab: { icon: 'flask', cls: '', key: 'doc.lab' },
  presentation: { icon: 'file-text', cls: 'chip-gold', key: 'doc.presentation' },
  resource: { icon: 'archive', cls: 'chip-archive', key: 'doc.resource' },
};

/** Languages a document can be filtered by ("both" = one file holding EN and FR). */
function docLangs(d) {
  return d.langs.includes('both') ? ['en', 'fr'] : d.langs;
}

function docFace(d, v, face) {
  const L = v.lang;
  const active = L === face;
  const chip = TYPE_CHIP[d.type] || TYPE_CHIP.presentation;
  // A bilingual face speaks its own language; a monolingual card speaks the site language.
  const title = d.bilingual ? v.title : d.title[state.lang];
  const description = d.bilingual ? v.description : d.description[state.lang];
  let langBadge;
  if (d.bilingual) {
    langBadge = `<span class="chip chip-both" title="${esc(t('doc.bilingual'))}">${icon('globe')}${esc(t('doc.both'))}</span>${langToggle(d, face)}`;
  } else if (L === 'both') {
    // One file holding both languages (e.g. a ZIP with EN and FR notebooks).
    langBadge = `<span class="chip chip-both" title="${esc(t('doc.both_file'))}">${icon('globe')}${esc(t('doc.both'))}</span>`;
  } else {
    langBadge = `<span class="chip chip-neutral" lang="${L}" title="${esc(t(`doc.lang_${L}`))}">${upper(L)}</span>`;
  }
  const themeLink = PAGE === 'home'
    ? `<span>${icon('folder')}<a href="${esc(`${HOME}themes/${d.theme.id}/`)}">${esc(d.theme.title[state.lang])}</a></span>` : '';
  return `
    <div class="doc-face ${L === d.langs[0] ? '' : 'doc-face-back'}" lang="${d.bilingual ? L : state.lang}" data-lang="${L}"
         aria-hidden="${String(!active)}"${active ? '' : ' inert'}>
      <div class="doc-head">
        <span class="chip ${chip.cls}">${icon(chip.icon)}${esc(t(chip.key))}</span>
        ${langBadge}
      </div>
      <h3>${esc(title)}</h3>
      <p class="doc-desc">${esc(description)}</p>
      <div class="doc-meta">
        <span>${icon('drive')}<span class="visually-hidden">${esc(t('doc.size'))}: </span>${esc(v.size_human)}</span>
        <span>${icon('calendar')}<span class="visually-hidden">${esc(t('doc.updated'))}: </span><time datetime="${esc(v.updated)}">${esc(formatDate(v.updated))}</time></span>
        ${themeLink}
      </div>
      <div class="doc-actions">${faceActions(d, v)}</div>
    </div>`;
}

function docCard(d, face = initialFace(d)) {
  const faces = d.langs.map((L) => docFace(d, d.versions[L], face)).join('');
  return `
    <article class="doc-card tilt${d.bilingual ? ' is-bilingual' : ''}" data-tilt-max="4" data-type="${esc(d.type)}"
             data-id="${esc(docKey(d))}" data-face="${face}" id="doc-${esc(d.theme.id)}-${esc(d.id)}">
      <div class="doc-flip">${faces}</div>
    </article>`;
}

/** Flip a bilingual card to the given language face (updates ARIA state). */
function setFace(card, lang, { focus = false } = {}) {
  if (!card || card.dataset.face === lang) return;
  card.dataset.face = lang;
  $$('.doc-face', card).forEach((face) => {
    const active = face.dataset.lang === lang;
    face.setAttribute('aria-hidden', String(!active));
    face.toggleAttribute('inert', !active);
    $$('[role="radio"]', face).forEach((r) => {
      const checked = r.dataset.setFace === lang;
      r.setAttribute('aria-checked', String(checked));
      r.tabIndex = checked ? 0 : -1;
    });
  });
  if (focus) $(`.doc-face[data-lang="${lang}"] [data-set-face="${lang}"]`, card)?.focus({ preventScroll: true });
}

function matches(d) {
  const f = state.filters;
  if (f.type !== 'all' && d.type !== f.type) return false;
  if (f.lang !== 'all' && !docLangs(d).includes(f.lang)) return false;
  if (!f.q) return true;
  const hay = norm([
    d.title.en, d.title.fr, d.description.en, d.description.fr,
    ...Object.values(d.versions).map((v) => `${v.title} ${v.description} ${v.download_name}`),
    d.theme.title.en, d.theme.title.fr,
  ].join(' '));
  return norm(f.q).split(/\s+/).filter(Boolean).every((w) => hay.includes(w));
}

function renderDocs() {
  const grid = $('#doc-grid');
  if (!grid) return;
  if (PAGE === 'theme' && !currentTheme()) return;
  const docs = allDocs().filter(matches);
  const count = $('#results-count');
  if (count) count.textContent = tn(docs.length, 'search.count_one', 'search.count');

  // After a site-language switch, cards start on the previous language and
  // flip in a light cascade to the new one.
  const previous = storage('session', CASCADE_KEY);
  storage('session', CASCADE_KEY, null);
  const cascade = !REDUCED_MOTION && SUPPORTED.includes(previous) && previous !== state.lang;

  grid.innerHTML = docs.length
    ? docs.map((d) => docCard(d, cascade && d.versions[previous] ? previous : initialFace(d))).join('')
    : `<div class="empty-state"><p>${esc(t('search.none'))}</p><button type="button" class="btn btn-ghost btn-3d" data-reset>${esc(t('search.reset'))}</button></div>`;
  grid.setAttribute('aria-busy', 'false');

  if (cascade) {
    const cards = $$('.doc-card.is-bilingual', grid).filter((c) => c.dataset.face !== state.lang && findDoc(c.dataset.id)?.versions[state.lang]);
    cards.forEach((card, i) => setTimeout(() => setFace(card, state.lang), 250 + i * 70));
  }
}

// ---------------------------------------------------------------------------
// Card interactions: language flip (mouse + keyboard), preview, ZIP
// ---------------------------------------------------------------------------
function initCards() {
  document.addEventListener('click', (e) => {
    const radio = e.target.closest('[data-set-face]');
    if (radio) setFace(radio.closest('.doc-card'), radio.dataset.setFace, { focus: true });
  });
  document.addEventListener('keydown', (e) => {
    const radio = e.target.closest?.('.lang-toggle [role="radio"]');
    if (!radio) return;
    const card = radio.closest('.doc-card');
    const doc = findDoc(card?.dataset.id);
    if (!doc) return;
    const idx = doc.langs.indexOf(card.dataset.face);
    let next = null;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') next = doc.langs[(idx + 1) % doc.langs.length];
    if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') next = doc.langs[(idx - 1 + doc.langs.length) % doc.langs.length];
    if (e.key === 'Home') next = doc.langs[0];
    if (e.key === 'End') next = doc.langs[doc.langs.length - 1];
    if (e.key === ' ' || e.key === 'Enter') next = radio.dataset.setFace;
    if (next) { e.preventDefault(); setFace(card, next, { focus: true }); }
  });
}

function initPreview() {
  document.addEventListener('click', async (e) => {
    const btn = e.target.closest('[data-preview]');
    if (!btn) return;
    const doc = findDoc(btn.dataset.preview);
    const v = doc?.versions[btn.dataset.version] || (doc ? doc.versions[doc.langs[0]] : null);
    if (!doc || !v) return;
    btn.setAttribute('aria-busy', 'true');
    try {
      const { openPdfPreview } = await import('./pdf-viewer.js');
      const title = doc.bilingual ? v.title : doc.title[state.lang];
      await openPdfPreview({ url: ROOT + v.file, title, downloadName: v.download_name, t });
    } catch (err) {
      console.error(err);
      window.open(ROOT + v.file, '_blank', 'noopener');
    } finally {
      btn.removeAttribute('aria-busy');
    }
  });
}

let jszipPromise = null;
function loadJsZip() {
  if (window.JSZip) return Promise.resolve(window.JSZip);
  if (!jszipPromise) {
    jszipPromise = new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = JSZIP_URL;
      s.async = true;
      s.onload = () => (window.JSZip ? resolve(window.JSZip) : reject(new Error('JSZip missing')));
      s.onerror = () => reject(new Error('JSZip failed to load'));
      document.head.appendChild(s);
    });
  }
  return jszipPromise;
}

/** Bonus: download the EN and FR versions of a document in one ZIP archive. */
function initZip() {
  document.addEventListener('click', async (e) => {
    const btn = e.target.closest('[data-zip]');
    if (!btn) return;
    const doc = findDoc(btn.dataset.zip);
    if (!doc) return;
    const label = btn.querySelector('span');
    const original = label?.textContent;
    btn.disabled = true;
    if (label) label.textContent = t('doc.zip_busy');
    try {
      const JSZip = await loadJsZip();
      const zip = new JSZip();
      await Promise.all(Object.values(doc.versions).map(async (v) => {
        const res = await fetch(ROOT + v.file);
        if (!res.ok) throw new Error(`${v.file}: HTTP ${res.status}`);
        zip.file(v.download_name, await res.blob());
      }));
      const blob = await zip.generateAsync({ type: 'blob' });
      const first = Object.values(doc.versions)[0].download_name;
      const suffix = state.catalog.site?.download_suffix || '_AfDB_DI4A';
      const stem = first.replace(/\.[^.]+$/, '').replace(new RegExp(`_(EN|FR)${suffix}$`), '');
      const url = URL.createObjectURL(blob);
      const a = Object.assign(document.createElement('a'), { href: url, download: `${stem}_EN_FR${suffix}.zip` });
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 10000);
    } catch (err) {
      console.error('ZIP failed', err);
      // Fallback: open each version's download link.
      Object.values(doc.versions).forEach((v) => window.open(ROOT + v.file, '_blank', 'noopener'));
    } finally {
      btn.disabled = false;
      if (label && original) label.textContent = original;
    }
  });
}

// ---------------------------------------------------------------------------
// Search & filters (state is mirrored in the URL for shareable links)
// ---------------------------------------------------------------------------
function initFilters() {
  const form = $('#toolbar');
  if (!form) return;
  const params = new URLSearchParams(location.search);
  state.filters.q = params.get('q') || '';
  state.filters.type = ['lab', 'presentation', 'resource'].includes(params.get('type')) ? params.get('type') : 'all';
  state.filters.lang = SUPPORTED.includes(params.get('lang')) ? params.get('lang') : 'all';
  const input = $('#search-input');
  const langSel = $('#lang-filter');
  if (input) input.value = state.filters.q;
  if (langSel) langSel.value = state.filters.lang;
  const typeRadio = form.querySelector(`input[name="type"][value="${state.filters.type}"]`);
  if (typeRadio) typeRadio.checked = true;

  const syncUrl = () => {
    const p = new URLSearchParams();
    if (state.filters.q) p.set('q', state.filters.q);
    if (state.filters.type !== 'all') p.set('type', state.filters.type);
    if (state.filters.lang !== 'all') p.set('lang', state.filters.lang);
    const qs = p.toString();
    history.replaceState(null, '', `${location.pathname}${qs ? `?${qs}` : ''}${location.hash}`);
  };
  let timer = null;
  input?.addEventListener('input', () => {
    clearTimeout(timer);
    timer = setTimeout(() => { state.filters.q = input.value.trim(); syncUrl(); renderDocs(); }, 120);
  });
  form.addEventListener('change', (e) => {
    if (e.target.name === 'type') state.filters.type = e.target.value;
    if (e.target.name === 'lang') state.filters.lang = e.target.value;
    syncUrl();
    renderDocs();
  });
  document.addEventListener('click', (e) => {
    if (!e.target.closest('[data-reset]')) return;
    state.filters = { q: '', type: 'all', lang: 'all' };
    if (input) input.value = '';
    if (langSel) langSel.value = 'all';
    const all = form.querySelector('input[name="type"][value="all"]');
    if (all) all.checked = true;
    syncUrl();
    renderDocs();
    input?.focus();
  });
}

// ---------------------------------------------------------------------------
// 3D tilt (event delegation so that re-rendered cards keep working)
// ---------------------------------------------------------------------------
function initTilt() {
  if (REDUCED_MOTION || !FINE_POINTER) return;
  let active = null;
  const reset = (el) => {
    el.classList.remove('is-tilting');
    el.style.setProperty('--rx', '0deg');
    el.style.setProperty('--ry', '0deg');
    el.style.setProperty('--gx', '50%');
    el.style.setProperty('--gy', '50%');
  };
  document.addEventListener('pointermove', (e) => {
    const el = e.target.closest?.('.tilt');
    if (el !== active) { if (active) reset(active); active = el; }
    if (!el) return;
    const max = Number(el.dataset.tiltMax || 6);
    const r = el.getBoundingClientRect();
    const px = Math.min(1, Math.max(0, (e.clientX - r.left) / r.width));
    const py = Math.min(1, Math.max(0, (e.clientY - r.top) / r.height));
    el.classList.add('is-tilting');
    el.style.setProperty('--ry', `${((px - 0.5) * 2 * max).toFixed(2)}deg`);
    el.style.setProperty('--rx', `${(-(py - 0.5) * 2 * max).toFixed(2)}deg`);
    el.style.setProperty('--gx', `${(px * 100).toFixed(1)}%`);
    el.style.setProperty('--gy', `${(py * 100).toFixed(1)}%`);
  }, { passive: true });
  document.addEventListener('pointerleave', () => { if (active) { reset(active); active = null; } });
  document.addEventListener('pointerdown', (e) => {
    const el = e.target.closest?.('.tilt');
    if (el) { el.style.setProperty('--lift', '1px'); setTimeout(() => el.style.removeProperty('--lift'), 160); }
  }, { passive: true });
}

// ---------------------------------------------------------------------------
// Header & navigation
// ---------------------------------------------------------------------------
function initHeader() {
  const header = $('.site-header');
  const toggle = $('.nav-toggle');
  const nav = $('#site-nav');
  const toTop = $('.to-top');
  if (header) {
    const onScroll = () => {
      header.classList.toggle('is-scrolled', window.scrollY > 8);
      toTop?.classList.toggle('is-visible', window.scrollY > 700);
    };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
  }
  if (toggle && nav) {
    const setOpen = (open) => {
      nav.classList.toggle('is-open', open);
      toggle.setAttribute('aria-expanded', String(open));
      toggle.setAttribute('aria-label', t(open ? 'a11y.close_menu' : 'a11y.menu'));
    };
    toggle.addEventListener('click', () => setOpen(!nav.classList.contains('is-open')));
    nav.addEventListener('click', (e) => { if (e.target.closest('a')) setOpen(false); });
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape') setOpen(false); });
  }
  $$('.lang-btn').forEach((b) => b.addEventListener('click', () => setLang(b.dataset.lang)));
}

// ---------------------------------------------------------------------------
// Boot
// ---------------------------------------------------------------------------
async function boot() {
  injectIconSprite();
  initHeader();
  initTilt();
  initFilters();
  initCards();
  initPreview();
  initZip();
  const lang = detectLang();
  try {
    state.dict = await fetchJson(`${ROOT}i18n/${lang}.json`);
    state.lang = lang;
  } catch (err) {
    console.error('i18n failed', err);
  }
  applyI18n();
  if (PAGE === '404') return;
  try {
    state.catalog = await fetchJson(`${ROOT}data/catalog.json`);
    renderAll();
    if (location.hash.startsWith('#doc-')) $(location.hash)?.scrollIntoView({ block: 'center' });
  } catch (err) {
    console.error('catalogue failed', err);
    $$('#theme-grid, #doc-grid').forEach((el) => { el.innerHTML = `<p class="empty-state">${esc(t('preview.error'))}</p>`; el.setAttribute('aria-busy', 'false'); });
  }
}

boot();
